#include <iostream>
#include <string>
#include <string_view>
int main() {
    std::string owner{"key=value"};
    std::string_view view{owner};
    auto position = view.find('=');
    if (position == std::string_view::npos) { std::cout << "missing\n"; return 0; }
    std::cout << view.substr(0, position) << '|' << view.substr(position + 1) << '\n';
}

