#include <iostream>
#include <string>
int main() {
    std::string line;
    if (!std::getline(std::cin, line) || line.size() > 200) { std::cout << "invalid\n"; return 0; }
    std::string extra;
    if (std::getline(std::cin, extra)) { std::cout << "invalid\n"; return 0; }
    int letters{}, digits{}, spaces{}, other{};
    for (unsigned char ch : line) {
        if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) { ++letters; }
        else if (ch >= '0' && ch <= '9') { ++digits; }
        else if (ch == ' ') { ++spaces; }
        else { ++other; }
    }
    std::cout << line.size() << ' ' << letters << ' ' << digits << ' ' << spaces << ' ' << other << '\n';
}
